50	static bool pfw_sanitize_string(pfw_vector_t* names)
51	{
52	    const char* name1;
53	    const char* name2;
54	    int i, j;
55	    for (i = 0; (name1 = pfw_vector_get(names, i)); i++) {
56	        for (j = i + 1; (name2 = pfw_vector_get(names, j)); j++) {
57	            if (!strcmp(name1, name2)) {
58	                PFW_DEBUG("Duplicate string '%s'\n", name1);
59	                return false;
60	            }
61	        }
62	    }
63	
64	    return true;
65	}
