67	static void pfw_sanitize_ammends(pfw_vector_t* ammends, pfw_system_t* system)
68	{
69	    pfw_criterion_t* criterion;
70	    pfw_ammend_t* ammend;
71	    int i;
72	
73	    for (i = 0; (ammend = pfw_vector_get(ammends, i)); i++) {
74	        criterion = pfw_criteria_find(system->criteria, ammend->u.raw);
75	        if (criterion) {
76	            ammend->type = PFW_AMMEND_CRITERION;
77	            ammend->u.criterion = criterion;
78	        } else {
79	            ammend->type = PFW_AMMEND_RAW;
80	        }
81	    }
82	}
83	
84	static bool pfw_sanitize_rules(pfw_rule_t* rules, pfw_system_t* system)
85	{
86	    pfw_criterion_t* criterion;
87	    pfw_rule_t* rule;
88	    int i;
89	
90	    if (rules->predicate == PFW_PREDICATE_ALL
91	        || rules->predicate == PFW_PREDICATE_ANY) {
92	        for (i = 0; (rule = pfw_vector_get(rules->branches, i)); i++) {
93	            if (!pfw_sanitize_rules(rule, system)) {
94	                PFW_DEBUG("Rule branch at %d is invalid\n", i);
95	                return false;
96	            }
97	        }
98	
99	        return true;
100	    }
101	
102	    /* Santinize criterion. */
103	
104	    criterion = pfw_criteria_find(system->criteria, rules->criterion.def);
105	    if (!criterion) {
106	        PFW_DEBUG("Criterion '%s' not found\n", rules->criterion.def);
107	        return false;
108	    }
109	
110	    rules->criterion.p = criterion;
111	
112	    /* Santinize state. */
113	
114	    if (rules->criterion.p->type != PFW_CRITERION_NUMERICAL
115	        && pfw_criterion_atoi(rules->criterion.p, rules->state.def, &rules->state.v)
116	            < 0) {
117	        PFW_DEBUG("Rule has invalid state '%s' for criterion '%s'\n",
118	            rules->state.def, (char*)pfw_vector_get(rules->criterion.p->names, 0));
119	        return false;
120	    }
121	
122	    /* Santinize predicates. */
123	
124	    switch (rules->criterion.p->type) {
125	    case PFW_CRITERION_EXCLUSIVE:
126	        if (rules->predicate == PFW_PREDICATE_IS
127	            || rules->predicate == PFW_PREDICATE_ISNOT)
128	            return true;
129	
130	    case PFW_CRITERION_INCLUSIVE:
131	        if (rules->predicate == PFW_PREDICATE_INCLUDES
132	            || rules->predicate == PFW_PREDICATE_EXCLUDES)
133	            return true;
134	
135	    case PFW_CRITERION_NUMERICAL:
136	        if (rules->predicate == PFW_PREDICATE_IN
137	            || rules->predicate == PFW_PREDICATE_NOTIN)
138	            return true;
139	    }
140	
141	    PFW_DEBUG("Rule uses invalid predicate '%d' for type '%d'\n",
142	        rules->predicate, rules->criterion.p->type);
143	
144	    return false;
145	}
