209	static bool pfw_sanitize_criterion(pfw_criterion_t* criterion, pfw_system_t* system)
210	{
211	    if (criterion->init.def
212	        && pfw_criterion_atoi(criterion, criterion->init.def, &criterion->init.v) < 0) {
213	        PFW_DEBUG("Criterion has invalid initial state '%s'\n", criterion->init.def);
214	        return false;
215	    }
216	
217	    criterion->state = criterion->init.v;
218	    if (system->on_load)
219	        system->on_load(system->cookie, pfw_vector_get(criterion->names, 0), &criterion->state);
220	
221	    if (criterion->type != PFW_CRITERION_NUMERICAL
222	        && !pfw_sanitize_string(criterion->ranges)) {
223	        return false;
224	    }
225	
226	    return pfw_sanitize_string(criterion->names);
227	}
