233	bool pfw_sanitize_criteria(pfw_system_t* system)
234	{
235	    pfw_vector_t* names = NULL;
236	    pfw_criterion_t* criterion;
237	    bool result = false;
238	    int i, j, ret;
239	    char* name;
240	
241	    for (i = 0; (criterion = pfw_vector_get(system->criteria, i)); i++) {
242	        if (!pfw_sanitize_criterion(criterion, system))
243	            goto out;
244	
245	        for (j = 0; (name = pfw_vector_get(criterion->names, j)); j++) {
246	            ret = pfw_vector_append(&names, name);
247	            if (ret < 0)
248	                goto out;
249	        }
250	    }
251	
252	    result = pfw_sanitize_string(names);
253	    if (!result) {
254	        PFW_DEBUG("duplicate criterion name\n");
255	    }
256	
257	out:
258	    pfw_vector_free(names);
259	    return result;
260	}
